SELECT s.s_state AS store_state, i.i_category AS item_category, COUNT(DISTINCT cs.cs_order_number) AS num_orders, SUM(cs.cs_net_profit) AS total_catalog_net_profit, SUM(ws.ws_net_profit) AS total_web_net_profit, SUM(sr.sr_net_loss) AS total_store_returns_net_loss, SUM(wr.wr_net_loss) AS total_web_returns_net_loss, SUM(inv.inv_quantity_on_hand) AS total_inventory_on_hand, AVG(p.p_cost) AS avg_promo_cost, MIN(cs.cs_sold_date_sk) AS min_sold_date_sk, MAX(cs.cs_sold_date_sk) AS max_sold_date_sk FROM tpcds.catalog_sales cs JOIN tpcds.date_dim d ON cs.cs_sold_date_sk = d.d_date_sk JOIN tpcds.item i ON cs.cs_item_sk = i.i_item_sk JOIN tpcds.customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN tpcds.customer_demographics cd ON cs.cs_bill_cdemo_sk = cd.cd_demo_sk JOIN tpcds.household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN tpcds.customer_address ca ON cs.cs_bill_addr_sk = ca.ca_address_sk JOIN tpcds.promotion p ON cs.cs_promo_sk = p.p_promo_sk LEFT JOIN tpcds.inventory inv ON inv.inv_item_sk = i.i_item_sk AND inv.inv_date_sk = d.d_date_sk LEFT JOIN tpcds.income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk LEFT JOIN tpcds.store s ON s.s_closed_date_sk = d.d_date_sk LEFT JOIN tpcds.store_returns sr ON sr.sr_item_sk = i.i_item_sk AND sr.sr_returned_date_sk = d.d_date_sk AND sr.sr_customer_sk = c.c_customer_sk AND sr.sr_store_sk = s.s_store_sk LEFT JOIN tpcds.web_sales ws ON ws.ws_item_sk = i.i_item_sk AND ws.ws_sold_date_sk = d.d_date_sk AND ws.ws_bill_customer_sk = c.c_customer_sk LEFT JOIN tpcds.web_returns wr ON wr.wr_item_sk = i.i_item_sk AND wr.wr_returned_date_sk = d.d_date_sk AND wr.wr_order_number = ws.ws_order_number WHERE d.d_year = 2002 AND i.i_units = 'Each' AND ca.ca_state = 'CA' GROUP BY s.s_state, i.i_category HAVING SUM(cs.cs_net_profit) > 10000 ORDER BY total_catalog_net_profit DESC LIMIT 100
